var normalized = Guard.AgainstEmpty(slug, nameof(slug), 64)
    .ToLowerInvariant()
    .Replace(' ', '-');

// "Acme  Co" and "acme--co" should be the same workspace address.
while (normalized.Contains("--"))
{
    normalized = normalized.Replace("--", "-");
}

normalized = normalized.Trim('-');
